/**
 * Recharts - Minimal SVG Chart Implementation for EZGalaxy
 */
(function(global) {
    'use strict';

    // Color palette
    const defaultColors = [
        '#8884d8', '#82ca9d', '#ffc658', '#ff7300', '#00C49F',
        '#FFBB28', '#FF8042', '#0088FE', '#00C49F', '#FFBB28'
    ];

    // Responsive Container
    function ResponsiveContainer({ width = '100%', height = 300, children }) {
        const containerStyle = {
            width: typeof width === 'number' ? `${width}px` : width,
            height: typeof height === 'number' ? `${height}px` : height,
            position: 'relative'
        };

        return React.createElement('div', { 
            className: 'recharts-responsive-container',
            style: containerStyle 
        }, children);
    }

    // Base Chart Component
    function createChart(ChartComponent) {
        return function Chart({ width = 400, height = 300, data = [], children, margin = {} }) {
            const m = { top: 20, right: 30, bottom: 20, left: 40, ...margin };
            const innerWidth = width - m.left - m.right;
            const innerHeight = height - m.top - m.bottom;

            // Extract config from children
            let xAxisConfig = null;
            let yAxisConfig = null;
            let lines = [];
            let areas = [];
            let bars = [];
            let pies = [];
            let radars = [];
            let tooltip = null;
            let legend = null;
            let grid = null;

            React.Children.forEach(children, child => {
                if (!child) return;
                const type = child.type?.displayName || child.type?.name || '';
                if (type === 'XAxis') xAxisConfig = child.props;
                else if (type === 'YAxis') yAxisConfig = child.props;
                else if (type === 'Line') lines.push(child.props);
                else if (type === 'Area') areas.push(child.props);
                else if (type === 'Bar') bars.push(child.props);
                else if (type === 'Pie') pies.push(child.props);
                else if (type === 'Radar') radars.push(child.props);
                else if (type === 'Tooltip') tooltip = child.props;
                else if (type === 'Legend') legend = child.props;
                else if (type === 'CartesianGrid') grid = child.props;
            });

            // Calculate scales
            const xKey = xAxisConfig?.dataKey || 'name';
            const allYValues = [];
            [...lines, ...areas, ...bars].forEach(config => {
                if (config.dataKey) {
                    data.forEach(d => {
                        const val = d[config.dataKey];
                        if (typeof val === 'number') allYValues.push(val);
                    });
                }
            });

            const yMin = yAxisConfig?.domain?.[0] ?? Math.min(0, ...allYValues);
            const yMax = yAxisConfig?.domain?.[1] ?? Math.max(...allYValues) * 1.1 || 100;

            const xScale = (i) => m.left + (i / Math.max(data.length - 1, 1)) * innerWidth;
            const yScale = (v) => m.top + innerHeight - ((v - yMin) / (yMax - yMin || 1)) * innerHeight;

            const elements = [];

            // Grid
            if (grid) {
                const gridLines = [];
                for (let i = 0; i <= 5; i++) {
                    const y = m.top + (i / 5) * innerHeight;
                    gridLines.push(React.createElement('line', {
                        key: `h${i}`,
                        x1: m.left,
                        y1: y,
                        x2: m.left + innerWidth,
                        y2: y,
                        stroke: grid.stroke || '#e0e0e0',
                        strokeDasharray: grid.strokeDasharray || '3 3'
                    }));
                }
                elements.push(React.createElement('g', { key: 'grid', className: 'recharts-grid' }, gridLines));
            }

            // Bars
            if (bars.length > 0) {
                const barWidth = innerWidth / data.length * 0.6 / bars.length;
                const barGroup = bars.map((barConfig, bi) => {
                    return data.map((d, i) => {
                        const val = d[barConfig.dataKey] || 0;
                        const x = xScale(i) - (bars.length * barWidth) / 2 + bi * barWidth;
                        const barHeight = ((val - yMin) / (yMax - yMin || 1)) * innerHeight;
                        return React.createElement('rect', {
                            key: `bar-${bi}-${i}`,
                            x: x,
                            y: yScale(val),
                            width: barWidth * 0.9,
                            height: Math.max(0, barHeight),
                            fill: barConfig.fill || defaultColors[bi],
                            rx: 2
                        });
                    });
                });
                elements.push(React.createElement('g', { key: 'bars', className: 'recharts-bars' }, barGroup));
            }

            // Areas
            areas.forEach((areaConfig, ai) => {
                const points = data.map((d, i) => `${xScale(i)},${yScale(d[areaConfig.dataKey] || 0)}`);
                const areaPath = `M${m.left},${m.top + innerHeight} L${points.join(' L')} L${m.left + innerWidth},${m.top + innerHeight} Z`;
                const linePath = `M${points.join(' L')}`;
                
                elements.push(React.createElement('g', { key: `area-${ai}`, className: 'recharts-area' },
                    React.createElement('path', {
                        d: areaPath,
                        fill: areaConfig.fill || defaultColors[ai],
                        fillOpacity: areaConfig.fillOpacity ?? 0.3
                    }),
                    React.createElement('path', {
                        d: linePath,
                        fill: 'none',
                        stroke: areaConfig.stroke || defaultColors[ai],
                        strokeWidth: areaConfig.strokeWidth || 2
                    })
                ));
            });

            // Lines
            lines.forEach((lineConfig, li) => {
                const points = data.map((d, i) => `${xScale(i)},${yScale(d[lineConfig.dataKey] || 0)}`);
                const path = `M${points.join(' L')}`;
                
                const lineElements = [
                    React.createElement('path', {
                        key: 'line',
                        d: path,
                        fill: 'none',
                        stroke: lineConfig.stroke || defaultColors[li],
                        strokeWidth: lineConfig.strokeWidth || 2
                    })
                ];

                if (lineConfig.dot !== false) {
                    data.forEach((d, i) => {
                        lineElements.push(React.createElement('circle', {
                            key: `dot-${i}`,
                            cx: xScale(i),
                            cy: yScale(d[lineConfig.dataKey] || 0),
                            r: 4,
                            fill: lineConfig.stroke || defaultColors[li]
                        }));
                    });
                }

                elements.push(React.createElement('g', { key: `line-${li}`, className: 'recharts-line' }, lineElements));
            });

            // X Axis
            if (xAxisConfig) {
                const ticks = data.map((d, i) => React.createElement('g', {
                    key: i,
                    transform: `translate(${xScale(i)}, ${m.top + innerHeight})`
                },
                    React.createElement('line', { y2: 6, stroke: '#666' }),
                    React.createElement('text', {
                        y: 20,
                        textAnchor: 'middle',
                        fill: '#999',
                        fontSize: 12
                    }, d[xKey] || '')
                ));
                elements.push(React.createElement('g', { key: 'xaxis', className: 'recharts-xaxis' },
                    React.createElement('line', {
                        x1: m.left,
                        y1: m.top + innerHeight,
                        x2: m.left + innerWidth,
                        y2: m.top + innerHeight,
                        stroke: '#666'
                    }),
                    ...ticks
                ));
            }

            // Y Axis
            if (yAxisConfig) {
                const yTicks = [];
                for (let i = 0; i <= 5; i++) {
                    const val = yMin + (i / 5) * (yMax - yMin);
                    const y = yScale(val);
                    yTicks.push(React.createElement('g', {
                        key: i,
                        transform: `translate(${m.left}, ${y})`
                    },
                        React.createElement('line', { x2: -6, stroke: '#666' }),
                        React.createElement('text', {
                            x: -10,
                            textAnchor: 'end',
                            alignmentBaseline: 'middle',
                            fill: '#999',
                            fontSize: 12
                        }, Math.round(val))
                    ));
                }
                elements.push(React.createElement('g', { key: 'yaxis', className: 'recharts-yaxis' },
                    React.createElement('line', {
                        x1: m.left,
                        y1: m.top,
                        x2: m.left,
                        y2: m.top + innerHeight,
                        stroke: '#666'
                    }),
                    ...yTicks
                ));
            }

            return React.createElement('div', {
                className: 'recharts-wrapper',
                style: { width, height }
            },
                React.createElement('svg', { width, height, viewBox: `0 0 ${width} ${height}` }, elements)
            );
        };
    }

    // Line Chart
    const LineChart = createChart('line');
    LineChart.displayName = 'LineChart';

    // Area Chart
    const AreaChart = createChart('area');
    AreaChart.displayName = 'AreaChart';

    // Bar Chart
    const BarChart = createChart('bar');
    BarChart.displayName = 'BarChart';

    // Pie Chart
    function PieChart({ width = 400, height = 400, children }) {
        let pieConfig = null;
        let tooltip = null;
        let legend = null;

        React.Children.forEach(children, child => {
            if (!child) return;
            const type = child.type?.displayName || child.type?.name || '';
            if (type === 'Pie') pieConfig = child.props;
            else if (type === 'Tooltip') tooltip = child.props;
            else if (type === 'Legend') legend = child.props;
        });

        if (!pieConfig) {
            return React.createElement('svg', { width, height });
        }

        const { data = [], dataKey, nameKey = 'name', cx = '50%', cy = '50%', outerRadius = 80, innerRadius = 0, fill, children: cells } = pieConfig;
        
        const centerX = typeof cx === 'string' ? width / 2 : cx;
        const centerY = typeof cy === 'string' ? height / 2 : cy;
        const or = typeof outerRadius === 'string' ? Math.min(width, height) * 0.4 : outerRadius;
        const ir = typeof innerRadius === 'string' ? or * 0.6 : innerRadius;

        const total = data.reduce((sum, d) => sum + (d[dataKey] || 0), 0);
        let currentAngle = -Math.PI / 2;

        const slices = data.map((d, i) => {
            const value = d[dataKey] || 0;
            const angle = (value / total) * Math.PI * 2;
            const startAngle = currentAngle;
            const endAngle = currentAngle + angle;
            currentAngle = endAngle;

            const x1 = centerX + Math.cos(startAngle) * or;
            const y1 = centerY + Math.sin(startAngle) * or;
            const x2 = centerX + Math.cos(endAngle) * or;
            const y2 = centerY + Math.sin(endAngle) * or;
            const x3 = centerX + Math.cos(endAngle) * ir;
            const y3 = centerY + Math.sin(endAngle) * ir;
            const x4 = centerX + Math.cos(startAngle) * ir;
            const y4 = centerY + Math.sin(startAngle) * ir;

            const largeArc = angle > Math.PI ? 1 : 0;

            const path = ir > 0 ?
                `M${x1},${y1} A${or},${or} 0 ${largeArc} 1 ${x2},${y2} L${x3},${y3} A${ir},${ir} 0 ${largeArc} 0 ${x4},${y4} Z` :
                `M${centerX},${centerY} L${x1},${y1} A${or},${or} 0 ${largeArc} 1 ${x2},${y2} Z`;

            const sliceFill = d.fill || defaultColors[i % defaultColors.length];

            return React.createElement('path', {
                key: i,
                d: path,
                fill: sliceFill,
                stroke: '#fff',
                strokeWidth: 2
            });
        });

        return React.createElement('div', {
            className: 'recharts-wrapper',
            style: { width, height }
        },
            React.createElement('svg', { width, height }, slices)
        );
    }
    PieChart.displayName = 'PieChart';

    // Radar Chart
    function RadarChart({ width = 400, height = 400, data = [], children }) {
        const cx = width / 2;
        const cy = height / 2;
        const radius = Math.min(width, height) * 0.35;

        let radarConfig = null;
        let polarGridConfig = null;
        let polarAngleAxisConfig = null;

        React.Children.forEach(children, child => {
            if (!child) return;
            const type = child.type?.displayName || child.type?.name || '';
            if (type === 'Radar') radarConfig = child.props;
            else if (type === 'PolarGrid') polarGridConfig = child.props;
            else if (type === 'PolarAngleAxis') polarAngleAxisConfig = child.props;
        });

        const angleStep = (Math.PI * 2) / data.length;
        const elements = [];

        // Grid
        if (polarGridConfig) {
            for (let r = 0.2; r <= 1; r += 0.2) {
                const points = data.map((_, i) => {
                    const angle = i * angleStep - Math.PI / 2;
                    return `${cx + Math.cos(angle) * radius * r},${cy + Math.sin(angle) * radius * r}`;
                }).join(' ');
                elements.push(React.createElement('polygon', {
                    key: `grid-${r}`,
                    points,
                    fill: 'none',
                    stroke: '#e0e0e0'
                }));
            }
        }

        // Angle axis labels
        if (polarAngleAxisConfig) {
            const labelKey = polarAngleAxisConfig.dataKey || 'name';
            data.forEach((d, i) => {
                const angle = i * angleStep - Math.PI / 2;
                const x = cx + Math.cos(angle) * (radius + 20);
                const y = cy + Math.sin(angle) * (radius + 20);
                elements.push(React.createElement('text', {
                    key: `label-${i}`,
                    x,
                    y,
                    textAnchor: 'middle',
                    alignmentBaseline: 'middle',
                    fill: '#999',
                    fontSize: 12
                }, d[labelKey] || ''));
            });
        }

        // Radar shape
        if (radarConfig) {
            const dataKey = radarConfig.dataKey;
            const maxValue = Math.max(...data.map(d => d[dataKey] || 0));
            const points = data.map((d, i) => {
                const value = (d[dataKey] || 0) / maxValue;
                const angle = i * angleStep - Math.PI / 2;
                return `${cx + Math.cos(angle) * radius * value},${cy + Math.sin(angle) * radius * value}`;
            }).join(' ');

            elements.push(React.createElement('polygon', {
                key: 'radar',
                points,
                fill: radarConfig.fill || defaultColors[0],
                fillOpacity: radarConfig.fillOpacity ?? 0.3,
                stroke: radarConfig.stroke || defaultColors[0],
                strokeWidth: 2
            }));
        }

        return React.createElement('div', {
            className: 'recharts-wrapper',
            style: { width, height }
        },
            React.createElement('svg', { width, height }, elements)
        );
    }
    RadarChart.displayName = 'RadarChart';

    // Chart sub-components
    function XAxis(props) { return null; }
    XAxis.displayName = 'XAxis';

    function YAxis(props) { return null; }
    YAxis.displayName = 'YAxis';

    function CartesianGrid(props) { return null; }
    CartesianGrid.displayName = 'CartesianGrid';

    function Tooltip(props) { return null; }
    Tooltip.displayName = 'Tooltip';

    function Legend(props) { return null; }
    Legend.displayName = 'Legend';

    function Line(props) { return null; }
    Line.displayName = 'Line';

    function Area(props) { return null; }
    Area.displayName = 'Area';

    function Bar(props) { return null; }
    Bar.displayName = 'Bar';

    function Pie(props) { return null; }
    Pie.displayName = 'Pie';

    function Cell(props) { return null; }
    Cell.displayName = 'Cell';

    function Radar(props) { return null; }
    Radar.displayName = 'Radar';

    function PolarGrid(props) { return null; }
    PolarGrid.displayName = 'PolarGrid';

    function PolarAngleAxis(props) { return null; }
    PolarAngleAxis.displayName = 'PolarAngleAxis';

    function PolarRadiusAxis(props) { return null; }
    PolarRadiusAxis.displayName = 'PolarRadiusAxis';

    // Export
    const Recharts = {
        ResponsiveContainer,
        LineChart,
        AreaChart,
        BarChart,
        PieChart,
        RadarChart,
        XAxis,
        YAxis,
        CartesianGrid,
        Tooltip,
        Legend,
        Line,
        Area,
        Bar,
        Pie,
        Cell,
        Radar,
        PolarGrid,
        PolarAngleAxis,
        PolarRadiusAxis
    };

    // Expose globally
    Object.assign(global, Recharts);
    global.Recharts = Recharts;

})(typeof window !== 'undefined' ? window : this);
